CREATE TABLE IF NOT EXISTS sales_lock (id TINYINT NOT NULL PRIMARY KEY) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
INSERT IGNORE INTO sales_lock(id) VALUES (1);
CREATE TABLE IF NOT EXISTS products (product_code VARCHAR(191) NOT NULL PRIMARY KEY, name TEXT NOT NULL, price INT NOT NULL, active TINYINT NOT NULL, version INT NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS inventory (product_code VARCHAR(191) NOT NULL PRIMARY KEY, quantity INT NOT NULL, FOREIGN KEY (product_code) REFERENCES products(product_code)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS orders (order_id CHAR(36) NOT NULL PRIMARY KEY, product_code VARCHAR(191) NOT NULL, quantity INT NOT NULL, unit_price INT NOT NULL, status VARCHAR(16) NOT NULL, FOREIGN KEY (product_code) REFERENCES products(product_code)) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
CREATE TABLE IF NOT EXISTS sync_state (id TINYINT NOT NULL PRIMARY KEY, catalog_version INT NOT NULL) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
